B.bqn=new A.n(B.vl,["Hi {{client_name}},\n\nPlease find attached your quote {{document_number}} for {{amount}}.\n\n{{portal_link}}\n\nThank you for your business.\n\n{{company_name}}","Hi {{client_name}},\n\nPlease find attached invoice {{document_number}} for {{amount}}, due {{due_date}}.\n\n{{payment_summary}}\n\nPlease don't hesitate to reach out with any questions.\n\n{{company_name}}","Hi {{client_name}},\n\nPlease find attached credit note {{document_number}} for {{amount}}.\n\n{{company_name}}","Hi {{client_name}},\n\nPlease find attached your account statement from {{company_name}}.\n\nIf you have any questions about the transactions shown, please don't hesitate to reach out.\n\n{{company_name}}","Hi {{client_name}},\n\nThis is a friendly reminder that invoice {{document_number}} was due on {{due_date}}. The balance due is {{balance_due}}.\n\nIf you have already made payment, please disregard this message.\n\nPlease don't hesitate to reach out if you have any questions.\n\n{{company_name}}","Hi {{client_name}},\n\nPlease find attached purchase order {{document_number}} for {{amount}}.\n\nKindly confirm receipt and expected delivery date.\n\n{{company_name}}","Hi {{client_name}},\n\nYour quote {{document_number}} from {{company_name}} has been accepted.\n\nThank you,\n{{company_name}}","Hi {{client_name}},\n\nYour quote {{document_number}} from {{company_name}} has been declined.\n\nIf you have any questions please don't hesitate to reach out.\n\n{{company_name}}","Hi {{client_name}},\n\nThank you for your payment of {{amount}} on {{payment_date}} for invoice {{document_number}}.\n\nBalance remaining: {{balance_due}}.\n\n{{company_name}}"],t.w)
B.bqq=new A.n(B.vl,["Bonjour {{client_name}},\n\nVeuillez trouver ci-joint votre devis {{document_number}} d'un montant de {{amount}}.\n\n{{portal_link}}\n\nMerci de votre confiance.\n\n{{company_name}}","Bonjour {{client_name}},\n\nVeuillez trouver ci-joint la facture {{document_number}} d'un montant de {{amount}}, \xe0 r\xe9gler au plus tard le {{due_date}}.\n\n{{payment_summary}}\n\nN'h\xe9sitez pas \xe0 nous contacter pour toute question.\n\n{{company_name}}","Bonjour {{client_name}},\n\nVeuillez trouver ci-joint l'avoir {{document_number}} d'un montant de {{amount}}.\n\n{{company_name}}","Bonjour {{client_name}},\n\nVeuillez trouver ci-joint votre relev\xe9 de compte de {{company_name}}.\n\nPour toute question sur les op\xe9rations indiqu\xe9es, n'h\xe9sitez pas \xe0 nous contacter.\n\n{{company_name}}","Bonjour {{client_name}},\n\nNous vous rappelons que la facture {{document_number}} \xe9tait \xe0 r\xe9gler le {{due_date}}. Le solde d\xfb est de {{balance_due}}.\n\nSi vous avez d\xe9j\xe0 effectu\xe9 le paiement, merci de ne pas tenir compte de ce message.\n\nN'h\xe9sitez pas \xe0 nous contacter pour toute question.\n\n{{company_name}}","Bonjour {{client_name}},\n\nVeuillez trouver ci-joint le bon de commande {{document_number}} d'un montant de {{amount}}.\n\nMerci de nous confirmer sa r\xe9ception et la date de livraison pr\xe9vue.\n\n{{company_name}}","Bonjour {{client_name}},\n\nVotre devis {{document_number}} de {{company_name}} a \xe9t\xe9 accept\xe9.\n\nMerci,\n{{company_name}}","Bonjour {{client_name}},\n\nVotre devis {{document_number}} de {{company_name}} a \xe9t\xe9 refus\xe9.\n\nN'h\xe9sitez pas \xe0 nous contacter pour toute question.\n\n{{company_name}}","Bonjour {{client_name}},\n\nNous vous remercions de votre paiement de {{amount}} du {{payment_date}} pour la facture {{document_number}}.\n\nSolde restant : {{balance_due}}.\n\n{{company_name}}"],t.w)
B.bpK=new A.n(B.a24,[B.bqn,B.bqq],t.vb)
